export const CH1 = `三月初一，青岚山的雾直到卯时末还没散干净。

白雾从山坳里漫上来，湿冷地贴在人后颈上，把演武场四周高挑的宗门青旗洇得沉甸甸的，"青岚宗"三个金字挂在半空滴水。风一吹，雾气撕开几道口子，底下黑压压攒动的全是人头。

一年一度的测灵大典是云州地界顶大的事，家里但凡有个满十六岁的半大孩子，砸锅卖铁也要把人往山上送。灵脉认人，也认命。三岁测出个三品玄脉就能一步登天，翻不过这道坎，一辈子就得留在山下泥沟里刨食。

演武场外的青石阶挤满了人，卖糖糕的蒸笼直冒白气，算命先生晃着铜铃喊得嗓子劈叉，几个乡下阿婆抹着眼泪往孙儿手腕上缠红绳护身符。穿绸缎的镇上粮商牵着儿子站在前排，赤脚穿草鞋的佃户缩在石阶墙根底下。汗酸味、炭灰味、糖油焦香混着廉价脂粉味冲进鼻腔，闹哄哄的。

高台上每隔片刻就响起执事拉长调子的唱名，紧接着要么是一片轰然惊呼，要么就是压低嗓门的啧啧叹息。

"哥！哥！"人堆外头挤进来个梳双丫髻的小姑娘，个子刚到陈渊胸口，踮着脚尖端着一只缺了口的大粗瓷碗，生怕汤水洒出来，"快喝！山脚张婶灶上刚熬好的姜茶，她说上台前喝口热的，手气旺！"

陈渊接过碗，指尖触到滚烫的粗陶壁，心口那团从昨夜就堵着的闷气松快了些。他仰头把姜茶灌进肚里，辛辣顺着嗓子眼一直烧进胃底，冻僵的手指总算回暖。

他蹲下身，视线跟妹妹平齐，替她把额前被雾打湿的碎发理到耳后："瑶瑶，一会儿不管台上喊出什么字眼，你都别哭，听见没？"

"为什么不让我哭？"陈瑶眨巴着乌黑的眼珠，小嘴一撇，"爹以前常说我们陈家血脉好，哥你肯定能测出高品灵脉！"

"嗯，能。"陈渊笑了笑，没戳穿她，也没多解释，"可万一山风大迷了眼呢？你一哭，哥心里就乱了，站不稳。"

陈瑶似懂非懂，还是把嘴唇抿紧用力点头："不哭！哥最厉害了！"

前方人群一阵推搡，执事的铜锣又敲响了。陈渊把空碗塞回妹妹怀里，站起身揉了揉她的发顶，转身挤进人流。身后，陈瑶抱着尚带余温的空碗，贴着石柱小声补了一句："哥……我就在这儿等你。"

陈渊站到了最外圈的阴影里。他今年十六，瘦得像根抽条的竹竿，身上这件灰蓝旧布衫洗得发白，左袖口故意放长了半寸，盖住手腕上那块暗金色的胎记——巴掌大小一角，形状像片凝住的兽鳞，边缘长着细碎的纹路。晨光斜斜扫过袖口，那层暗金偶尔会透出一星极冷的晕泽，这十年来除了他自己，没第二个人知道。

他来得极早，却偏要往后缩。不是胆怯，是十年前那场大火教会的本事：人越缩在沙子底下，踩过来的脚印就越少。

"下一个，赵明！"

前头排着个穿绸缎马褂的镇上少年，颤巍巍走上去按住测灵珠，石头半晌才泛起一层浑浊黄光。记录执事蘸墨在花名册上一划，懒洋洋报了声"二品玄脉，记外门杂役"，台边那对穿金戴银的爹妈却已经抱头痛哭，说是祖坟冒了青烟，好歹脱离了凡胎。

再后面轮到个猎户家的汉子，叫钱大山，粗布短打袖管挽到胳膊肘，虎口磨着厚茧。他攒足力气一巴掌拍上去，玄玉嗡地亮起刺眼蓝光，映得半张台面发青。执事震得往前迈了半步大喊"四品玄脉！好小子！"，钱大山脸憋得通红，乐得原地转了两个圈，惹得台下山呼海啸般叫好。

"下一个，陈渊！"

执事的嗓门不算太响，可话音落定，四周的嘈杂硬生生矮下去半截。数百道目光齐刷刷钉过来。陈渊迈步踏上青石甬道，步幅稳当，左右两侧压低的咬耳朵声顺风钻进耳朵。

"这就是陈家那个遗孤？"

"嘘——找死呢，十年前那桩祸事忘了？"

"唉，原先在云州城里也是门庭体面的人家，听说他爹当年说话掷地有声，逢年过节连城主府都要递帖子……"

"体面能当饭吃？一把火烧得连灰都不剩，就剩这两根独苗。听说他家那血脉——"

"闭嘴！嫌命长了？"

私语像退潮似的缩回人堆，只剩风吹青旗的猎猎响声。陈渊眼皮没抬，这些碎嘴闲话听了整十年，早把耳根磨出了硬茧。他眼里只盯着台中央那尊半人高的乳白玄玉——测灵珠。

测灵珠嵌在黑石底座里，内里有水银般的流光来回转圈。受测者将掌心按上去，珠光越亮玄脉品级越高；若是一点光都不透，那便是终身与修行无缘的废脉。

陈渊收回视线，踏上石阶，抬起右手按上冰冷玉面。

一息。

两息。

十息过去。

手底下的玄玉连半星火星都没冒，死水一潭。只有左袖遮住的腕骨深处，那块暗金胎记猛地灼烫了一下，像被人拿烧红的香头戳了一记，转眼又凉透回去。

执事不耐烦地甩甩毛笔："行了行了，别堵着石头耽误后头人。废脉一个！"

台下先是冒出两声憋不住的嗤笑，像火星子蹦进干草垛，紧跟着轰然炸成一片。

"废脉！陈家那小子果然是个废脉！"

"我当撑到最后能憋出个响儿呢，原来连引气入体的门坎都摸不着！"

"啧，可惜了生得副好眉眼，往后也只能留山上挑大粪咯。"

笑声里有幸灾乐祸，也有真假难辨的惋惜。在青岚宗地界，废脉不是病，是刻在脑门上洗不掉的印子。

人群后头，陈瑶小脸憋得煞白，攥紧拳头拨开挡路的大人就要往台上冲："你们胡说八道！我哥才不是——"

一只粗糙的妇人手掌从斜刺里伸出来，铁钳似的扣住她胳膊往回拖。是邻院张婶，蹲下死死捂住小姑娘的嘴："瑶丫头疯了？别替你哥招灾！废脉能留山上干杂活混口热饭，已经是老天开眼，这世道有口吃的比啥都强！"

陈瑶挣了两下没挣开，嘴唇咬出了血印子，死死瞪着高台，硬是没让眼眶里的水珠滚下来。

演武台正中主位上，一名白衣少年往前倾了倾身子。他生得极俊，腰佩一柄通体乌沉的墨色长剑，正是青岚宗人人交口称赞的内门大师兄萧景行。他嗓音清朗温和，不高不低正好传遍整座广场："执事，杂役院本就收留废脉弟子做些粗活，何必当众落人颜面？陈师弟也是我青岚宗门下。"

台下登时响起一片恭维赞叹："大师兄仁厚！""还是萧师兄顾念同门情分，难怪掌门器重。"

陈渊站在低处石阶上，低头盯着自己沾满泥点子的布鞋尖，装出副羞愧难当的木讷模样。可就在萧景行开口那瞬，陈渊眼角余光接住了高台上落下来的那道视线——清亮、礼貌、挑不出半点错处，却偏偏叫他后背脊梁骨泛起一股凉意。

那视线跟城里贵人看鞋底粘着一星臭泥没有两样，面子上过得去就行，背地里随时能拿脚尖碾死，事后还要嫌脏地掸掸鞋面。

他把牙关咬合回去。十年前那场火烧掉的不止是房子，还有少年人的傲气——活着比争一口短气金贵，看破了烂在肚子里，说破的那天多半就是死期。

执事挥手打发："陈渊，去东侧杂役院报到。下一位！"

人潮很快又聚拢到下个少年身上，青岚山上的悲欢从不会为谁停半步。陈渊顺着青石坡往下走，背影单薄，路过山道拐角时肩头猛地挨了一记重拍。

来人是个铁塔似的壮实少年，嗓门震得人耳膜嗡嗡响："渊哥！别往心里去！没脉就没脉，咱哥俩抡斧头劈柴一样活得舒坦！"是杂役院同屋的王铁柱，父母前年染时疫走了，被舅舅扔上山讨生活，性子直得跟根木桩似的。陈渊朝他点点头，没吭声，右手却不自觉按住了左腕衣袖——刚才贴上测灵珠那一下滚烫，绝不是错觉。

东侧偏院就是杂役院所在。管事的姓陈，四十来岁干瘦如猴，斜眼翻着花名册问了两句力气如何，啪地拍下一块木头腰牌："劈柴、挑水、扫院子三班轮换，月钱三钱银子，年底瞧手脚麻利了再算。丑话搁前头，这院子不养大爷，干不动自己卷铺盖滚。"

陈渊领了发潮的灰布薄被、缺了口的水桶和一把钝斧，跟着王铁柱去认了井台、柴房和后山坡道。铁柱边走边手把手教他握斧柄得留半寸滑手，不然虎口一天就能震破皮。头一天白昼就在抡斧子、担水桶和王铁柱没完没了的唠叨里过去，空气里尽是松木柴烟和后厨大锅煮烂菜叶子的味道。

傍晚收工，陈渊去冰凉石槽边刷净缺口陶碗，蹲在墙根底下扒拉半碗糙米饭，配一碟黑乎乎的酱咸菜。王铁柱端着碗凑过来，二话不说往他碗底拨了两块油亮咸萝卜干："吃！俺跟伙房胖婶熟，她多抓了把菜叶。"

刚咬了两口，陈瑶不知从哪条小路钻进来，往他碗里塞进一小捧洗去泥巴的鲜嫩野荠菜："哥，张婶教我拿盐搓搓拌饭吃，可香了！"

"自己吃了没有？"陈渊看着妹妹鼻尖沁出来的细汗，"大冷天端这么久，手都冻僵了。"

"早吃啦！"陈瑶拍拍扁平的小肚子，"张婶家熬了满满一大锅菜粥，我连喝三大碗呢！"

陈渊看着她手背上洗菜冻出来的红皲裂，还有袖肘处打了两层补丁的旧棉衣，没拆穿谎言，顺手拿筷子把自己碗里大半糙米拨进她手里那个豁口碗里。王铁柱在旁边看直了眼，吸溜着鼻涕把剩下那块咸萝卜干也挑进了陈瑶碗里："妹子多吃点，长个儿！等哥明年攒够月钱，下山给你买串糖葫芦！"

陈瑶小声道了谢，低头捧着碗大口往嘴里扒饭，生怕哥哥再把饭拨回去。陈渊就蹲在门槛边，端着只剩薄薄一层米汤的破碗一小口一小口喝完，胃里沉甸甸的倒也安稳。

入夜，杂役院最偏僻的小土屋四面漏风，破窗户纸被风吹得噗噗作响。月光斜着切过屋脊落在土炕上。陈瑶强撑着眼皮没合，一见哥哥推门进来，立刻从贴身棉袄里掏出个捂得温热的油纸小包塞进他手心，眼圈通红："哥，他们都在扯谎！爹说过，我们陈家的血脉——"

话卡在喉咙里吐不出来。陈家的过往，是兄妹俩谁也不敢轻易揭开的旧疤。十年前火起那夜，陈渊才六岁，陈瑶还在襁褓里嚎哭。他至今记得冲天黑烟呛得喉咙发甜，记得父亲掀开后院冷冰冰的水缸盖把兄妹俩按进去，记得隔着窜起的火舌，父亲回头看他最后一眼——那眼里没有半分濒死的惊惶，反倒沉着一种卸下重担的欣慰。

这视线陈渊琢磨了十年也没想通，家都烧塌了，爹究竟在欣慰什么？后来还是青岚宗下山采买的杂役从灰堆里扒出兄妹俩，带回山上混口饭吃。更早之前，娘在陈渊五岁那年病重撒手，临闭眼攥紧他的指头说过一句怪话："渊儿，你和你爹一个脾性，骨头里都埋着火。记住，火得往死里藏——真露了头那天，不是烧死旁人，就是烧死自己。"

陈渊揉乱妹妹的头发，剥开油纸拿出一颗廉价桂花糖放进她嘴里："睡吧，明早还得劈柴。"

陈瑶含着糖含糊答应一声，把蹬开的薄被角掖好，抱紧腿蜷成一团睡沉过去，长睫毛上还挂着两粒没干透的泪珠。

陈渊挨着土墙根坐下，想起爹生前最爱坐在院里那棵老桂花树底下喝闷酒。那时的云州城夏夜也闷热，桂花还没开，院墙根摆着两只大粗陶水缸，爹一边往碗里倒酒，一边拿蒲扇替他赶蚊子。后来那场烧了三天三夜的大火把整座宅院烧成了黑炭，唯有那口装过兄妹俩的冷水缸还立在瓦砾堆里。

他把余下的那颗桂花糖丢进嘴里。蔗糖混着干桂花碎末化在舌根，甜得发齁，反倒冲得鼻腔一阵发酸。这包糖得花掉小姑娘半个月的零花。他闭上眼。

约莫三更天，左腕蹿起一阵钻心剧痛。起初像烟灰烫着皮肤，转瞬化作一块烧红的烙铁死死摁进骨头缝里。陈渊猛地睁眼，冷汗顺着鬓角往下淌。疼的不是表皮，而是骨髓血脉最深处有什么蛰伏的巨物被强行撬醒。

屋外的山雾逆流涌动，整座青岚山散落的灵气像是决了堤的溪水，朝这间破漏土屋狂涌而来。炕沿边散落的干草屑悬在半空打旋，墙角一只破陶罐当啷一声滚砸在泥地上，屋顶茅草发出齐刷刷的震颤声响。熟睡的陈瑶翻了个身，砸吧砸吧嘴睡得更死了。

陈渊咬碎后槽牙盯着自己的左腕。那块暗金鳞片此时活了过来，寸寸舒张发亮，纹路缝隙间涌动着熔金般的微光，耳膜里轰轰响的全是自己沉重如鼓的心跳。

下一瞬，他看见了一幅光景——不是用双眼。

意识深处漫无边际的灰白浓雾里，一座锈迹斑斑的青铜小塔悬空拔起。九层塔身古拙沉重，偏偏缺了三层檐角，残存的铜壁上刻满晦涩纹路，透着镇压万古的死寂冷意。

锈迹缝隙透出一点青光。

紧跟着，一道沙哑苍老的笑声在脑海最深处荡了开来，里头裹着数不清的漫长等待与难以抑制的贪婪快意，活像空城守了一辈子的老人终于听见了门环扣响：

"三千年了……"

"终于等到你。"`
export const CH2 = `"你是谁？"陈渊在脑海里发问。

声音不是从喉咙挤出去的，而是直接砸在这片无天无地的灰白虚空里。脚下踩不到实地，头顶没有日月星辰，鼻端却闻得到一股极淡的陈年铜锈混合冷灰的味道，唯有左腕贴近的那团暗金发着滚烫热度。

不远处悬着那座巴掌高的青铜小塔，九层塔檐整整齐齐缺了三角，残缺处参差不齐，像被人一剑砍出的陈年旧伤。塔壁那些锈蚀的刻纹一寸寸亮起来，沉睡多年的巨兽正在抻开筋骨。

"老夫姓甚名谁早忘了。"那道老嗓音懒洋洋地打了个呵欠，带着刚从漫长昏睡里醒过来的散漫倦意，"塔里待过的人喊我塔灵，山上这帮瞎眼小辈，叫我老瞎子。"

陈渊动作一滞。守在青岚山山门口石狮旁那个糟老头？成天抱着个油腻粗陶酒壶晒太阳灌黄汤，胡子拉碴沾满酒渍，连杂役院最偷懒的滑头都懒得正眼看他。

"你……守山门那个老头？"

"怎的，不像？"塔灵哼笑一声，调侃道，"老夫还记得你九岁那年淘气，蹲在松树后头朝我脚边扔石子。三颗里头砸偏了两颗，就剩一颗咕噜滚过来撞响老夫的破酒葫芦。"

它顿了顿，语气里透出陈年老酒般的涩味："老夫在山门口吹了三十年穿堂风晒太阳，等的就是今夜这把火。也多亏了这具老皮囊还算结实，才没在等你的功夫里先朽烂成灰。"

陈渊盯着浮空的青铜塔沉默半晌。一肚子话堵在嗓子眼，一时反倒不知先问哪一句。

"你那条脉不是废了。"塔灵的嗓门压得很低，像怕隔墙有耳，"是人族那套破九品玄脉的缸太小，装不下你这副身子骨。你身上的底子叫混沌神体——吞灵气、吞血脉、吞法则。打个比方，神族往人族地里撒的种子里头，三千年来头一回长了棵专吃庄稼的怪苗。"

"什么庄稼？什么神族？"

"你脚下踩着的这片苍澜大陆，就是神族圈出来的田。"塔灵的语调冷下来，带着股陈年铁锈味，"三千年前，神族跟苍澜万族在封仙路上打了一场翻天覆地的大仗。那一仗万族血流成河，封仙路生生崩断，神族退回天外，临走前却给整座大陆人族血脉下了神契枷锁，美其名曰玄脉。"

"一品到九品，听着风光，其实不过是盛水的木桶大小有别，修到顶天立地也只是人家地里最肥满的一穗谷子。等秋后熟透，镰刀照样落下来割走。"

陈渊喉结滚了一下，呼吸停了半拍："那山上那些长老掌门……"

"照样在桶里打转，还当桶越修越大是造化。"塔灵冷笑，"唯独你这具躯壳恰恰相反，天生专吞灵机。神族的田地养肥你，你转头反吃人家的田地。神族最恨的，就是你这样的异类。"

"所以十年前他们才……"

"所以他们灭你的门。"塔灵接口干脆利落，"陈家好端端在云州扎根，为什么一夜之间烧成白地？你真信那是江湖仇杀？"

它话锋一转，问得直白："陈渊，你爹当年把你跟丫头按进水缸前，可曾提起过你们陈家先祖是怎么跨进这片大陆的？"

陈渊五指死死攥紧，骨节攥得泛白。十年前冲天的火光、父亲隔着浓烟投来的欣慰视线、妹妹没说完的那句血脉，杂七杂八翻涌上来。

"先祖怎么跨进来的？"他喉咙发干，"我们陈家原本不是苍澜大陆的人？"

"嘴皮子问得倒急。"塔灵打了个响鼻，"眼下你连门坎都没摸进，说透了反而招祸。先保住小命再打听祖宗来历。现在盘腿坐稳，老夫教你第一口怎么吞。"

"吞什么？"

"吞灵气。"塔灵的腔调头一回沉得像块铁，"听真切了，《混沌吞天诀》不分品阶不论层数，只有一条死规矩——天地万物皆可入腹。灵气算干饭，血脉算下酒菜，法则才是压轴的大席面。眼下把念头沉进左腕，那里留着一道缺口，试着把外头浮着的灵气扯进来。"

陈渊依言闭眼。头一回摸索，恰似盲人伸手去捞池塘里的冷水，指缝间明明有凉丝丝的活气绕着打转，偏偏一抓就散，怎么也拽不进经脉。

"蠢材，别使蛮力硬抠。"塔灵的声音在耳廓边炸响，"灵气是溪水，你是海。见过海追着水沟跑的吗？海只会——"

"敞开。"

两个字落地，陈渊识海轰然一声震响，恰似蓄满洪水的木闸被一脚踹碎。周遭清凉活跃的天地灵气疯了般倒灌而入，顺着四肢百骸直冲识海正中的小塔。青铜塔身嗡鸣微亮，锈皮底下的纹路活蛇般游走了一圈。

紧跟着便是撕裂般的剧痛。

没修过玄脉的人强吞天地灵气，跟把滚烫的生铁水灌进干竹管毫无区别。陈渊经脉立刻被撑得咯吱乱响，额角青筋一条条暴起，豆大的汗珠砸在粗布裤腿上洇开深色湿痕。偏偏里屋炕上的陈瑶翻了个身，迷糊中含混叫了声哥。陈渊浑身紧绷一动不敢动，抓起搭在肩头的汗巾死死咬进嘴里，牙龈渗出浓重铁锈味，硬生生把闷哼咽回肚里。

"撑住了。"塔灵语速极快，"混沌神体的经脉生来比旁人粗韧三倍，第一口最要命，熬过去往后就成了活水。"

也不知过了半刻还是一宿，等那股横冲直撞的锐痛潮水般退去，陈渊虚脱得直喘粗气，后背粗布褂子早湿透贴在皮肉上。他吐掉咬烂的汗巾动了动手指，掌缘竟带起一缕极细却锋利的微风，左腕那块鳞状胎记不再灼手，反倒像块被日头晒透的鹅卵石，暖洋洋地贴着腕脉。

"成了。"塔灵嗓音里藏着掩不住的得意，"虽然只吞进小半口，够你淬体打熬用了。记牢，《混沌吞天诀》没有那些绕弯子的花架子，吞得多体魄就硬。打明儿起该劈柴劈柴、该挑水挑水，力气活就是你的功课。"

"就……这么简单？"

"大道本来就简单。"塔灵又恢复了那副懒散腔调，"世人总以为功法秘籍写得越玄奥越值钱，其实全是前人故意绕出来的迷魂阵，专骗蠢材在里头打转一辈子。你是吃庄稼的主，用不着绕弯。"

塔灵压低声线："今晚的事天知地知你知我知。踏进聚灵境之前，死也不能叫外人看见你手腕发亮。尤其是那个姓萧的小杂种，眼睛毒得很。"

"萧景行？他不就是个内门大师兄，撑死比外门弟子高两重境界……"

"内门弟子？"塔灵嗤笑一声没接茬，"信老夫一句，离他远些。他今天在演武台上看你的目光，叫老夫想起三千年前站在田埂上数谷穗的神族监工。那不是看同门师弟的眼色，是挑拣肥瘦。"

谈话止在这里，塔灵的动静逐渐沉了下去，像又挨不住困意睡去，临末还嘟囔着三千年都等过不差这一时半刻。陈渊却没立刻退出来，隔了半晌又在识海里问了一句："塔灵，你方才提过的三千年前那场仗，到底是怎么回事？"

灰白雾气久久没有回音，就在陈渊以为老家伙又打盹时，那苍老声音才透着股沉重的沧桑飘出来："那年神族与万族在封仙路厮杀，老夫便是镇守封仙路的镇界塔。人族联军借走老夫这具塔身做阵眼，拿万族鲜血当柴火，硬生生烧断了一截神族降临苍澜的通路。"

"路断了，老夫也碎得七零八落，九层塔檐整整崩掉三层，真灵坠进这片大陆地脉底下睡了三千年。等来等去，只等一个能重燃炉火的混沌神体后人——你爷爷没扛住，你爹也没等到那口能烧穿神契的火气，偏偏传到你这里，老夫才闻着那股熟稔的味道。"

"我爹当年最后一次上山找过你？"陈渊喉头一哽，"就为了托你照看我们兄妹，然后一个人回去送死？"

塔灵沉默了两息，铜塔上的微光暗了下去："陈渊，你不是单替自己活着。你肩上扛的是陈家三千年一口气，你爹拿命押宝，才让你活过十年前那夜。"

"那他临走前，有没有留下一句话给我？"陈渊攥紧拳头追问。

"有。"老嗓音顿了顿，"他让老夫告诉你，若这辈子只图个安稳，就当自己是棵野草老老实实长在杂役院；若哪天咽不下那口冤屈气，便把左腕这把火烧透苍澜大陆。"

陈渊低头看了一眼发烫的手腕。十年前火光里父亲最后那道视线，这会儿总算跟塔灵的话严丝合缝地扣到了一处——父亲不是放弃了，是把整场赌局押在了自己和妹妹的命上。

窗外月色早已西斜，破屋里少年依旧盘腿靠着土墙，吐纳绵长。左腕皮肤底下，一缕极细的暗金微光绕着腕骨游走半圈，很快沉回皮肉，像从没亮过。

鸡叫头遍把陈渊吵醒。

他睁眼头一件事先低头看左腕，鳞状胎记安静贴在皮肤上，凉滑平顺。试着屈伸手指，关节发出清脆一响，周身像被拆开重新铆紧了铁箍，轻快扎实得不像话。他起身去水缸边拿木瓢舀冷水洗脸，五指一收差点把旧木瓢柄捏裂，赶紧松了二分力。

冷水泼在脸上激得打了个寒颤，头脑反倒清明透亮。转头再去拎墙角那只装满山泉的大木桶，往日得咬牙哼哧半天才能离地的死沉水桶，今日单手一提竟晃晃悠悠像拎空桶。他挑着眉毛把水桶放回去，心口噗通跳了两下。

门外砸响王铁柱的大嗓门："渊哥！快起！陈管事今儿抽疯要查早工，再赖床得扣钱！"

"来啦！"陈渊套上打补丁的灰短打，拍拍胸口的灰推门迎着清晨山风走出去，清冽松针气扑鼻。

这一整天他都在暗自掂量这副新身板：抡斧头劈柴不再靠蛮力死砸，腰背一拧劲气顺着胳膊往斧刃里灌，刀口咬进木纹又深又顺，手腕半点不震，半上午便堆出半堵柴墙。

挑满两桶井水踩上四十级湿滑石阶走回东偏院，往日肩胛骨磨破皮要歇三趟，今天一口气走到院心只换了回肩，小腿肚半点不抖，桶里的水甚至没溅出几滴。

午后拿大竹扫帚扫院落石阶时，鬼使神差往下杵了一下，笃的一声，青石板竟硬生生被扫帚把捅出个浅白印子。陈渊吓一跳，赶紧拿鞋底蹭些浮土盖严实，回头瞥了眼院门没人瞧见才松口气。

"渊哥！"王铁柱蹲在廊下啃冷硬的玉米窝头，瞪圆眼珠上下打量他半天，伸手捏了把陈渊胳膊肘，"嘶——咋硬得跟铁块似的？俺咋瞧着你今儿个哪儿不对头？"

"哪儿不对？"陈渊低头掸掉衣摆上的枯叶。

"说不上来。"铁柱抓抓乱蓬蓬的头发，嘴角还粘着玉米渣，"就是觉着你踩在地上的步子稳得邪门，喘气声儿比老牛还匀。俺爹从前杀猪讲过，一个人要是猛地变稳当了，八成不是发了横财，就是背地里偷练啥邪门功法！"

"那你看我像发了财，还是练了邪功？"

王铁柱盯了半晌认真摇头："俺看不透。反正渊哥干啥俺跟着干啥，你要真练邪功，俺就拎扁担替你放风！谁敢多嘴俺拿扁担拍他后脑勺！"

陈渊失笑，屈指敲了他脑门一记："少胡扯，吃完干活。"

入夜哄睡陈瑶，陈渊照例入识海见塔灵。老头懒散夸他白天藏得不错，就是杵青石那下太蠢，明眼人一眼能看出门道。

紧接着塔灵正色授他一套呼吸法门："灵气入腹不能死囤着，得让它绕经脉跑活了，最终全收进左腕胎记那道口子。胎记就是门框，灵气就是钥匙，先开门再吞灵，门缝扯得越宽，身骨淬炼得越硬实。往后记住贪多嚼不烂——好比拿小瓦罐去接山洪，罐口没撑大，水先把罐壁顶炸了，反噬的滋味尝一回就够受。"

陈渊依言引导灵气走完一周天，抵住左腕胎记刹那，冰凉的暗金鳞片猛地透出一股温热吸力。

他试着再把腕间那扇看不见的门推开半分，门外清凉的山间灵气立时涌进更多，绕着小臂筋膜兜了一圈，把白天劈柴留下的酸胀揉得一干二净。可但凡有点贪心多引半点灵气，经脉立马像针扎般发紧，吓得他赶紧收势，总算摸清了那条不能越界的门槛。

收功睁眼时窗纸透白，只觉骨头缝里暖融融一片，浑身疲惫扫空大半。

晨光刚染红东山林梢，他便揣起半个冷硬的玉米饼子，扛着扁担出门挑水。路过山门那对风化严重的石狮子，老瞎子照旧背靠石墩晒日头，怀里抱着个油渍麻花的粗陶酒壶，老远便飘来一股劣质黄酒酸味。

听见草鞋踩碎石子的声响，老头浑浊的眼皮掀开一条窄缝瞟了过来。那眼缝深处分明藏着一星笑意。陈渊脚步微顿，拎稳水桶顺嘴搭了句腔："老人家，今儿日头不错。"

老瞎子抿了口辛辣黄汤，吧唧着干裂嘴唇含糊咕哝："是不错，正经适合劈柴。"

"劈柴也得看木头硬不硬。"陈渊盯着老头半眯的眼睛，试探回了一句。

"再硬的木头，找准纹路一斧头也能裂。"话音刚落，老头又合上眼皮打起盹，可陈渊离得近，清清楚楚看见他扣在酒壶脖颈上的那只干瘦枯手，在吐出"劈柴"两字时微不可察地颤了一下。陈渊没拆穿，挑起扁担稳稳踏下石阶。`
