他想吃碗带肉沫的热汤面，顺便听听南荒秘境的风声。

醉仙居一楼大堂满是汗酸、酒糟和油锅爆葱蒜的味儿，几桌外门弟子划拳掷骰子吵得房梁落灰，跑堂伙计端着大盘卤猪耳从人缝里挤过去，油汤溅到陈渊鞋帮上也没人理会。陈渊避开人群踩上吱呀作响的二楼木梯，刚拐到走廊头，耳廓一动，听见靠窗那间雅座里飘出个尖嗓门——

