外门里出了名的狗腿子，聚灵二重修为，平日里恨不得拴在萧景行裤腰带上晃悠。

陈渊脚尖一转，没进大堂，贴着墙根拐进隔壁空着的隔间，要了一壶最便宜的烧刀子、一碟水煮花生。他拿粗木屏风遮住半边身子，夹起一粒花生不紧不慢剥壳，耳朵贴近薄薄的杉木板壁。

