台下顿时嗡嗡炸开了锅。秘境里头瘴气毒虫多、空间裂缝更是要命——十年前那一拨外门师兄进去三人，最后只爬出来一个断臂的——可随便捡一株百年份血参或者古宗遗宝，都够外门弟子少熬十年苦功。前排几个淬体巅峰的弟子脖子伸得老长，眼睛直勾勾盯着帛书上的红印，嘴里嘀咕着外门赌坊这回又开了几倍赔率。

