说完这句，柳风拔脚就走，青衫转过墙角就不见了踪影。陈渊握紧那块带着体温的暖白玉符，朝墙角低声道了句谢。

三日后，外门定额比斗在演武场正式开锣。

一早天刚放亮，演武场周围已经插满了彩旗，外门弟子挤满四周石阶，外围甚至搭起了两座临时赌棚，叫好声和铜钱磕碰声乱作一团。

