画面里天穹裂成两半，白玉铺就的封仙路从云海深处压下来，神族披甲铁骑顺着仙路长驱直入，铁蹄踏碎九州万宗山门，火海连天、血流成河；每当人族之中有人摸到登仙门槛、生出一线长生之机，那些高高在上的神族便顺路而下，敲骨吸髓收割大道，把整片大陆当成圈养的庄稼田。

一个背生深可见骨伤痕的叛神浑身浴血，硬生生用沾满自己鲜血的双手把神体无量大道一刀刀劈成七块残简，撒进崩塌的秘境碎片，留下一句沙哑遗言：

