三天后飞舟回返青岚宗，顾长风与两名魔修连同那枚血河铜牌一并被押交执法长老堂，外门上下闹得沸沸扬扬，萧景行推脱得一干二净，只说被门下奴才蒙蔽。陈渊没去争那几句口舌便宜——账已经记死，迟早要连本带利讨回来。

