天刚蒙蒙亮，院角老槐树上的露水还没干透，青色符纸已经贴在窗棂缝里，四边烫了一圈极细的金线——长老堂才发得出的「青鸢令」。

铁柱迷迷糊糊推门出来撒尿，瞥见窗台上压着东西，伸手捻起来翻来覆去看了半晌，糙厚指头上全是昨夜劈柴留下的木刺。满纸篆文他认不全，只死死盯住末尾那个「即」字，嗓门压得发紧：「渊哥，是不是……又出事了？」

