他盯着那枚印鉴看了几息，把符纸折成四方收进贴胸的布袋里，顺手将扁担靠回墙根。「不是出事，是催命。」

三日前他把第二道残简交去藏经阁归档，宗门上下把名录造进铁卷，这笔账就已经摆在明面上了。萧景行要的从来不是他死在山门里，而是他身上那点神体气息，外加尚未聚齐的七道残简。青岚宗之内，残简既已入册，萧家再横也明抢不得，换个地方动刀就顺手多了——南荒秘境天高皇帝远，外门弟子折在里头，连张买棺材的黄纸钱都省下来。

老瞎子在识海里哼笑一声：「算盘珠子拨得倒响。明知是个坑，去不去？」

「去。」陈渊弯腰从床板底下拖出玄铁剑。剑鞘上还沾着上回从南荒带回来的干泥，他拿块旧布蘸了点井水，一寸一寸擦掉泥点，连剑格缝隙里的沙砾也拿竹签挑干净，「坑里也有东西。他布他的局，我拿我的简，谁埋谁还不一定。」

老瞎子嘟囔了句「小滑头」，再没出声。

第二日夜里子时刚过，陈渊独自摸去了外门演武场。

寅时的演武场空荡荡的，夜风穿堂过廊，吹得青石地面冰凉刺骨。他脱掉外袍垫在石板上盘膝坐定，闭上眼，把吞天诀第二层「吞灵」在灵台里一遍遍推演。

第一层「吞气」讲究一个「反」字，敌人砸过来多少力道，他便借势还回去多少，四两拨千斤；可「吞灵」讲的是「纳」，要把天地间四散游离的灵性连本带利吞入丹田，炼成自家真元。一守一攻两章咬合在一处，这套残缺古诀才算真立住了骨架。

