陈渊起身抖了抖衣摆上的夜露，把玄铁剑背回肩后，指骨捏得噼啪响：「那就让他们嗅。嗅到跟前，我连人带锅一起吞。」

第三日卯时，青岚宗山门前的广场已经站了四十来号人。

此次试炼队由内门执事周崇带队，随行十二名内门弟子、二十名外门弟子，还有十几个负责背负干粮伤药的杂役。铁柱也在杂役堆里，背上压着个比他人还高出半头的麻布行囊，伸长脖子在人群缝里找陈渊。

陈渊踏上石阶时，广场上的嗡嗡议论声齐刷刷低了一截。各色视线扎在他身上，好奇的、打量的、压着火气的都有。外门魁首的名头他顶了还不到一个月，可这一个月里，杀聚灵一重的黑风、反手削伤顾长风、从浅层祭坛抢回第二道残简，每桩事都在各峰传遍了。嘴上不服的人固然有一半，可真等陈渊走近，站在路边的人照样下意识往旁边让出半步。

周崇立在队首石墩上，手里托着一枚巴掌大的青铜令牌，等队伍彻底站齐才举过头顶。

「南荒秘境十年一开，此番开期四十九日。进了里头，各凭本事争机缘、抢灵药，宗门不保你们活命，也不拦你们发财。丑话说在前面，规矩只有三条——」他目光挨个扫过在场每一张脸，停顿两息，「一，不得同宗相残；二，遇魔道，杀；三，遇大机缘先报宗门再取己需，私藏不报者，逐出山门。」

人群里稀稀拉拉应了声「遵命」。

陈渊站在队列最末，垂着眼皮把三条规矩记在心里。同宗不得相残？进了南荒林深雾重，死在妖兽利爪下还是死在同门冷剑下，抬出来时谁验得清。

至于第二条和第三条，更是把刀把子光明正大递到了某些人手里——遇魔道可杀，只要先把人打成魔道，谁不能杀。

他抬起视线往队伍另一端瞥了一眼，正撞上顾长风投来的目光。顾长风瘦得颧骨高耸，脸色灰败，上回在秘境入口被陈渊削去半只左耳，此刻用一块黑布斜缠着半边脑袋，整个人看着像条被抽断脊梁的野狗。

两人视线刚一碰上，顾长风眼底怨毒翻涌，脖子却先一步缩了回去，低头装作整理袖口。

辰时正，三艘中型飞舟离地起航。宗门这回没省灵石，船底破空符全开，原本七日的路程硬生生缩成四日，第四天午后便落在了断魂崖边。

崖底那道裂隙比先前宽出将近一倍，灰白雾气一团团往外翻涌，裹着一股陈渊极为熟识的甜腥气。他立在崖沿往下望，浓雾深处隐约透出几团暗红光晕，一明一灭，透着股令人反胃的闷沉。

