迈入秘境的一刻，四面八方压来一股沉甸甸的水压。里头的灵气浓度是外界三倍有余，吸进肺叶却混着股黏腻发甜的铁锈味，往经脉里一钻便让人指尖发胀、心火直顶天灵盖。

