陈渊依言摸出一枚净心丹含在舌根下，任由苦涩药汁漫开，暗地里却转起吞天诀。丹田深处那道漩涡一扯，把方才钻进经脉的那股甜腥煞气连同杂质一并卷了进去。左腕胎记猛地发烫，那团血煞在漩涡里连碾三圈，竟被生生剥去暴戾毒火，炼成一缕温顺精纯的灵气反哺回经脉。

对旁人来说要命的浊气，到他这儿反倒成了现成的补品。

队伍在秘境浅层穿行了大半日。这片地界全是高逾十丈的灰白石柱，柱身布满风蚀蜂窝孔，石缝间散落着低阶妖兽骸骨，有些早已风化成灰，有些还带着半干的皮肉。午后众人穿过一条干涸河床，撞见第一处血祭遗迹。

那是片被人一剑削平的三丈石台，石面密密麻麻刻满繁复阵纹，凹槽里全被暗红血垢填死，还嵌着碎骨碴与打结的毛发。台心立着半人高的石柱，柱顶卡了枚拳头大的黑晶石，晶石里头裹着团影子，一缩一涨地挪动，活像琥珀里困了条虫。

周崇走上前蹲下，拿剑尖挑了下黑晶石，脸色立刻沉下来：「血魔教的手笔。『养尸阵』的底座，用活物血气养石，等里头的东西成了气候，再起出来挪去大阵。」

有个外门弟子没忍住问：「执事，里头养的是什么？」

周崇没答话，反手一剑劈下。黑晶崩成粉末，半空响起一声尖细得像婴儿啼哭的啸音，一缕黑烟拧巴着挣扎两下，被透进石林的日光一晒，散了个干净。

「浅层已经不干净了，」周崇收剑起身，「全队加速往中层走。」

陈渊走在队尾，路过碎石堆时假装系鞋带蹲下去，指腹从石台边抹了点血垢捻了捻。血垢还是软的，带着湿意，最多不超过两个时辰。

「这不是什么旧遗迹，」老瞎子在识海里压低嗓音，「是他们边走边留的路标，专门指给后头进来的大鱼看。」

傍晚队伍在石林边缘找了处背风洼地扎营，周崇点出八名弟子轮班守夜，余下人各自打坐调息。铁柱怀里抱紧行囊缩在火堆边，他修为太浅根本扛不住这地方的血煞，舌底含着丹药牙关还在咯咯打战。

陈渊挨过去坐下，掌心贴在他后背渡了缕精纯灵气，又把干粮袋解下来塞进他怀里。

铁柱啃了半块硬饼，眼珠子却直往石林深处漆黑处瞄，喉结动了动：「渊哥，你听……里头有东西在叫。」

陈渊顺着他指的方向望过去，灰雾压得极低，什么也看不分明。可夜风里确实飘来一线声音——既不是风穿石孔的呜咽，也不是野兽嚎叫，是剑鸣。清越、绷紧、带着一股拼命的决绝，急促得几乎连成一条细线，中间还杂着几声闷响与短促喝骂。

陈渊抓起靠在膝边的玄铁剑站起身。周崇坐在主位篝火旁，视线立刻扫过来：「有人在那边？」

陈渊嗯了一声。

「这秘境里头几千号各宗弟子，死活各有天命，轮得到你去充英雄？坐回去。」周崇话音冷硬。

陈渊站着没挪窝。石林深处又飘来一声剑鸣，这一声比方才短了一大截，像是剑锋硬生生撞上了铁石，尾音当场掐断。陈渊闭上眼，把吞天诀的感知放出去，风声、火堆噼啪声、虫爬声一层层剥掉，只抓住那一线残存剑鸣里的气味——很冷，带着雪碴子落进衣领的干冽劲儿，绝不是魔道中人，是个快力竭的剑修。

他反手拔出佩剑攥在手里，弯腰拍了拍铁柱肩膀，把水囊挂到他行囊扣上：「在这儿等着，天亮我不回来就跟着大队走，别瞎找。」

刚迈出篝火圈两步，身后传来周崇的声音：「陈渊。」

火光映得这名内门执事半边脸明暗不定。周崇盯了他两息，伸手从袖筒里摸出那枚青铜令牌抛了过来：「你可知这一趟入秘境的名额，是谁替你压着长老堂争下来的？不是萧家，是掌门。掌门闭关三年，出关第一件事就是点了你的名。」

青铜令牌入手沉甸甸的，还带着周崇掌心的余温。

周崇已经转过身背对火光重新坐下：「中层以下，见令如见执事。要救人还是找死随你，别死在浅层，丢青岚宗的脸。」

陈渊攥紧令牌塞进怀里，没再多话，转身扎进浓雾。

入林不到半里，雾气稠得几乎化不开，血煞混着腐叶气吸进喉咙，满嘴都是铁锈味。这里的石柱比外围更高更密，一根挨着一根，像巨人插满大地的断牙。

陈渊步子迈得快，可每一步踩实前，神识必先往外铺出三丈，把柱影、碎石、风向全滤一遍——这是在杂役院劈了三年柴落下的老习惯，斧头砸下去前，总得先看清木头纹理往哪边走。

绕过第三十七根石柱时，神识撞上一团异物。那东西伏在一根倾倒石柱后头，蜷成一团青灰石块，表面跟周围乱石一般无二，可石壳里头偏偏裹着一缕一跳一跳的暗红血光。

陈渊停住脚，右手拇指抵上剑格。

那团青灰石头极别扭地抬起头，露出一张本该属于石灵的方正粗糙脸孔——只是五官凹槽全被暗红血垢糊满，眼窝里烧着两朵血焰，嘴角一路撕裂到耳根，支棱着满口细碎尖牙。

血煞石傀。

石傀喉咙里挤出漏风似的嘶嚎，四爪抠地猛扑过来。陈渊脚下没退半步，等腥风扑到胸前三尺，左手拇指一顶剑格，玄铁剑贴着肋下自下而上斜撩而出。「铛」一声炸响火星，石傀左侧前肢被连根削掉半截。断口没有流血，只冒出股股黑煞。

石傀浑不知疼，三条腿猛蹬碎石横撞过来，陈渊拧腰避开，顺手一剑划开它脊背。剑刃吃进半尺，溅出来的却不是石粉，是黑红黏稠的腐血，遇空气「嗤嗤」冒起白烟，溅在地上把青石板蚀出一排麻坑。

这不是活物妖兽，是拿秘境土生石灵作壳、拿活物血煞灌进腹中、中间又缝了道线牵着走的死傀儡。

