陈渊没绷住笑出声，笑完才觉出这一天一夜脸颊肌肉都僵着，牵动嘴角竟有些发酸。他拿布擦干净玄铁剑归鞘，指了指她膝上白剑：「你这剑，是灵器？」

「灵器上品，洛家传了十七代，名『听雪』。剑成那日，中州下了三天鹅毛雪。」她抬起指腹抹过剑鞘，白霜遇温融成水珠，顺着窄薄剑身滑落泥灰，「它专破魔道，血魔教的邪祟碰上它，就像雪碰上烧红的铁。我进秘境十九天，顺着外围一路清过来，拿它斩了四十七个教徒和血傀，连黑袍长老都砍死过两个。」

「那怎么还会落到这步田地？」陈渊低头拾起那枚黑色短矢，拿火折子凑近细看矢簇上的小字。

洛清欢静了几息才开口：「因为第四十八个，不是人。」

陈渊抬起视线。

「昨夜我在林子里遇上一个黑袍人，兜帽压得很低，看不见脸。我一剑从他心口穿过去，他连血都没流一滴，站着没动。」洛清欢的声音压低了些，「他伸手握住我的剑身，冲我笑，说『洛家的剑心诀还是这么好看，三千年了，一点长进都没有』。」

陈渊缠绷带的手指停在半空：「三千年？」

