城门大开。沉重的马蹄声踏碎夜色，从黑漆门洞里一股脑涌出来，一匹、两匹、十余匹朝四面八方散开。风里夹着甲胄碰撞的脆响、兵刃出鞘半寸又推回鞘里的轻啸，更远处还有一整排步卒踩着官道齐步奔跑的闷声。

