陈渊也停住了脚步。他顺着青石坡往上看，视线先落到她右手稳稳按住的「听雪」剑柄上，又扫过她没半点伤痕和病气的脸颊，确定去年她肩上的毒箭伤和那身血总算彻底养干净了，才迈开步子往上走。

走到三步远的地方，陈渊停下。

